cat > /tmp/uitest/test.js <<'EOF'
const { chromium } = require('playwright');
const { AxeBuilder } = require('@axe-core/playwright');
const BASE = 'http://127.0.0.1:8765/';
const tags = ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'];
(async () => {
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const page = await ctx.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  async function axe(label) {
    const r = await new AxeBuilder({ page }).withTags(tags).analyze();
    console.log(`axe ${label}: ${r.violations.length} violations`);
    r.violations.forEach(v => console.log('  -', v.id, v.impact, v.help, v.nodes.slice(0,3).map(n => n.target.join(' ')).join(' | ')));
  }
  for (const p of ['index.html','catalog.html','register.html','profile.html']) {
    await page.goto(BASE + p); await axe(p);
    await page.screenshot({ path: `/tmp/uitest/${p}.png`, fullPage: true });
  }
  // Catalog filtering
  await page.goto(BASE + 'catalog.html?dept=CS');
  console.log('CS cards:', await page.locator('#course-list > li').count());
  await page.fill('#search', 'zzzz'); await page.waitForTimeout(700);
  console.log('no-results visible:', await page.isVisible('#no-results'), 'count:', await page.textContent('#results-count'));
  await page.click('#empty-clear'); await page.waitForTimeout(50);
  console.log('after clear cards:', await page.locator('#course-list > li').count(), 'dept=', await page.inputValue('#filter-dept'));
  await page.check('#filter-open'); await page.waitForTimeout(50);
  console.log('open-only cards:', await page.locator('#course-list > li').count());
  // Register: errors
  await page.goto(BASE + 'register.html');
  await page.fill('#email', 'bad'); await page.click('button[type=submit]');
  console.log('focused after invalid submit:', await page.evaluate(() => document.activeElement.id), '|', await page.textContent('#error-summary-title'));
  console.log('summary items:', await page.$$eval('#error-summary-list a', as => as.map(a => a.textContent)));
  console.log('email describedby:', await page.getAttribute('#email','aria-describedby'), 'invalid:', await page.getAttribute('#email','aria-invalid'));
  console.log('title:', await page.title());
  await axe('register with errors');
  await page.click('#error-summary-list a >> nth=0');
  console.log('focus after summary link:', await page.evaluate(() => document.activeElement.id));
  // conflict
  await page.fill('#email', 'jordan.rivera@northfield.edu');
  await page.selectOption('#course', 'CS220'); await page.check('#grading-letter'); await page.check('#policy');
  await page.click('button[type=submit]');
  console.log('conflict errors:', await page.$$eval('#error-summary-list a', as => as.map(a => a.textContent)));
  // valid
  await page.selectOption('#course', 'BIO305'); await page.click('button[type=submit]');
  console.log('dialog open:', await page.evaluate(() => document.getElementById('confirm-dialog').open), 'focus:', await page.evaluate(() => document.activeElement.textContent));
  await axe('register dialog');
  await page.screenshot({ path: '/tmp/uitest/dialog.png' });
  await page.keyboard.press('Escape');
  console.log('after Esc open:', await page.evaluate(() => document.getElementById('confirm-dialog').open), 'focus:', await page.evaluate(() => document.activeElement.textContent));
  await page.click('button[type=submit]');
  await page.click('[data-role=confirm]');
  console.log('success visible:', await page.isVisible('#success-message'), 'focus:', await page.evaluate(() => document.activeElement.id), await page.textContent('#success-text'));
